import {startingCards,cardTypes,cardGrades,cardAvailable,DRAW_PRICE,runScore} from './meta.mjs';
import {skillIcon} from './skillbook.mjs';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function lobbyPanel(meta,name,category='character'){
 const selected=meta.selection,draw=meta.lastDraw,drawn=startingCards.find(c=>c.id===draw?.id);
 const card=c=>{const owned=cardAvailable(meta,c),tier=meta.collection[c.id]||0,active=selected[c.type]===c.id;return `<button class="starting-card ${active?'selected':''} ${owned?'owned':'locked'} card-tier-${tier}" data-card="${c.id}" ${owned?'':'disabled'}>${c.art?`<div class="starting-art"><img src="assets/combat/${c.art}.png" alt=""></div>`:`<span class="starting-symbol">${skillIcon(c.type==='relic'?'aegis':c.type==='talent'?'stance':c.type==='fate'?'signature':'focus')}</span>`}<small>${c.type==='fate'?'운명':owned?cardGrades[tier]:'미획득'}</small><strong>${esc(c.name)}</strong><p>${esc(c.description)}</p>${c.type==='character'?`<span>고유 능력 시작 Lv.${3+tier}</span>`:''}${!owned&&c.requires?'<span>이전 운명 클리어 필요</span>':''}${active?'<b>선택 중</b>':''}</button>`;};
 return `<section class="lobby"><div class="lobby-heading"><div><p class="eyebrow">새로운 회차</p><h1>${esc(name)}의 시작 카드</h1></div><span>보석 <b>${meta.gems}</b></span></div><div class="starting-slots">${Object.entries(cardTypes).map(([type,label])=>{const c=startingCards.find(c=>c.id===selected[type]);return `<button data-card-category="${type}" class="${category===type?'active':''}"><small>${label}</small><strong>${esc(c?.name||'선택 필요')}</strong></button>`;}).join('')}</div><label class="lobby-name-label" for="lobby-name">제자의 이름<input id="lobby-name" maxlength="16" value="${esc(name)}" autocomplete="off"></label><div class="lobby-controls"><button class="primary" id="launch-run">이 구성으로 모험 시작</button><button class="quiet" id="lobby-back">처음 화면</button></div><details class="card-draw"><summary>스타팅 카드 상점 · ${DRAW_PRICE}보석 뽑기</summary><p>캐릭터·동료·유물·재능 중 한 장. 첫 획득은 영웅, 중복은 전설 → 신화. 신화 카드는 후보에서 제외됩니다.</p><button class="primary" id="draw-card" ${meta.gems<DRAW_PRICE?'disabled':''}>보석 ${DRAW_PRICE}개로 한 장 뽑기</button><p class="muted">첫 시작 보석 240개 · 회차 완료 보상으로 추가 획득</p>${drawn?`<div class="draw-result" role="status"><b>${esc(drawn.name)} · ${cardGrades[draw.tier]}</b><span>${draw.duplicate?'중복 카드 · 등급 상승':'새 카드 획득'}</span></div>`:''}</details><h2>${cardTypes[category]}</h2><div class="starting-grid">${startingCards.filter(c=>c.type===category).map(card).join('')}</div><p id="lobby-note" role="status"></p>${meta.scores.length?`<details class="meta-scores"><summary>이전 회차 · 최고 ${Math.max(...meta.scores.map(r=>r.score))}점</summary>${meta.scores.map(r=>`<p>${esc(r.name)} · ${esc(r.ending)} · ${r.score}점</p>`).join('')}</details>`:''}</section>`;
}
export function scorePanel(s,settled=false){const r=runScore(s);return `<section class="run-score"><p class="eyebrow">RUN RESULT</p><h2>${esc(r.ending)}</h2>${r.death?`<p class="death-prose">${esc(r.death.text)}</p>`:''}<strong>${r.score.toLocaleString()}점</strong><dl><div><dt>진행·성장 점수</dt><dd>${r.base}</dd></div><div><dt>코인 점수</dt><dd>+${r.coinScore} <small>(보유 ${r.coins}, 최대 5,000)</small></dd></div><div><dt>진행 점수에 적용하는 운명 계수</dt><dd>×${r.factor}</dd></div></dl><button class="primary" id="settle-run">${settled?'수집과 다음 회차로':'결과 정산 · 수집으로'}</button><p>코인은 이번 회차에서 마무리됩니다. 카드와 보석은 수집 기록에 남습니다.</p></section>`;}
